	 ('fa0eed7d-6ad9-44ba-9278-61a07ec20f9d'::uuid,'【资产研判】JS 提取 URL 20250807','{
  "openapi": "3.1.0",
  "info": {
    "title": "【资产研判】JS 提取 URL ",
    "description": "API to analyze a given URL using URLFinder tool, extract domains, and calculate a weight based on predefined asset lists (IPs and direct subdomains).",
    "version": "v1.0.0"
  },
  "servers": [
    {
      "url": "http://192.168.31.92:11004",
      "description": "api服务器"
    }
  ],
  "paths": {
    "/analyze_url_with_urlfinder": {
      "post": {
        "description": "从网页js中提取url",
        "operationId": "【资产研判】JS 提取 URL ",
        "requestBody": {
          "description": "URL to be analyzed",
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "url": {
                    "type": "string",
                    "format": "uri",
                    "description": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''"
                  }
                },
                "required": [
                  "url"
                ],
                "example": {
                  "url": "https://www.sgcc.com.cn"
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Successfully analyzed the URL and calculated the weight.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "count": {
                      "type": "integer",
                      "description": "The total weight calculated based on matched assets. Each match adds 10 to the count."
                    }
                  },
                  "example": {
                    "count": 30
                  }
                }
              }
            }
          },
          "400": {
            "description": "Bad Request - Missing or invalid ''url'' parameter in the request body.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "count": {
                      "type": "integer",
                      "description": "Always 0 in case of a bad request."
                    }
                  },
                  "example": {
                    "count": 0
                  }
                }
              }
            }
          },
          "500": {
            "description": "Internal Server Error - An error occurred during URLFinder execution or internal processing.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "count": {
                      "type": "integer",
                      "description": "Always 0 in case of an internal server error."
                    }
                  },
                  "example": {
                    "count": 0
                  }
                }
              }
            }
          }
        },
        "deprecated": false
      }
    }
  },
  "components": {
    "schemas": {}
  }
}','openapi','8b3128aa-cf5a-47c7-be68-fee8bcec51f7'::uuid,'5a1eb0a8-9ccf-4a4a-9101-7d6273ee5bb3'::uuid,'[{"server_url": "http://192.168.31.92:11004/analyze_url_with_urlfinder", "method": "post", "summary": "\u4ece\u7f51\u9875js\u4e2d\u63d0\u53d6url", "operation_id": "\u3010\u8d44\u4ea7\u7814\u5224\u3011JS \u63d0\u53d6 URL ", "parameters": [{"name": "url", "label": {"en_US": "url", "zh_Hans": "url", "pt_BR": "url", "ja_JP": "url"}, "placeholder": {"en_US": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''", "zh_Hans": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''", "pt_BR": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''", "ja_JP": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''"}, "scope": null, "auto_generate": null, "template": null, "required": true, "default": null, "min": null, "max": null, "precision": null, "options": [], "type": "string", "human_description": {"en_US": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''", "zh_Hans": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''", "pt_BR": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''", "ja_JP": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''"}, "form": "llm", "llm_description": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''"}], "author": "", "icon": null, "openapi": {"description": "\u4ece\u7f51\u9875js\u4e2d\u63d0\u53d6url", "operationId": "\u3010\u8d44\u4ea7\u7814\u5224\u3011JS \u63d0\u53d6 URL ", "requestBody": {"description": "URL to be analyzed", "required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"url": {"type": "string", "format": "uri", "description": "The URL to send to URLFinder.exe for domain extraction. Example: ''http://www.example.com''"}}, "required": ["url"], "example": {"url": "https://www.sgcc.com.cn"}}}}}, "responses": {"200": {"description": "Successfully analyzed the URL and calculated the weight.", "content": {"application/json": {"schema": {"type": "object", "properties": {"count": {"type": "integer", "description": "The total weight calculated based on matched assets. Each match adds 10 to the count."}}, "example": {"count": 30}}}}}, "400": {"description": "Bad Request - Missing or invalid ''url'' parameter in the request body.", "content": {"application/json": {"schema": {"type": "object", "properties": {"count": {"type": "integer", "description": "Always 0 in case of a bad request."}}, "example": {"count": 0}}}}}, "500": {"description": "Internal Server Error - An error occurred during URLFinder execution or internal processing.", "content": {"application/json": {"schema": {"type": "object", "properties": {"count": {"type": "integer", "description": "Always 0 in case of an internal server error."}}, "example": {"count": 0}}}}}}, "deprecated": false}}]','{"content": "\ud83d\udd75\ufe0f", "background": "#FEF7C3"}','{"auth_type": "none"}','API to analyze a given URL using URLFinder tool, extract domains, and calculate a weight based on predefined asset lists (IPs and direct subdomains).','2025-08-28 09:00:16','2025-08-28 09:00:16',NULL,''),
