	 ('497dc50e-cf2c-4047-85cf-7510b7b0b379'::uuid,'【资产研判】Icon Hash 匹配 20250807','{
  "openapi": "3.1.0",
  "info": {
    "title": "【资产研判】Icon Hash 匹配",
    "description": "通过计算网站的 favicon.ico 哈希值，判断其是否与预设的目标哈希值匹配。这可以用于识别特定技术栈或网站特征。",
    "version": "v1.0.0"
  },
  "servers": [
    {
      "url": "http://192.168.31.92:11003"
    }
  ],
  "paths": {
    "/check_favicon": {
      "get": {
        "description": "获取指定 URL 的 Favicon 哈希匹配结果。该 API 会尝试访问 /favicon.ico 和 /assets/images/favicon.ico 路径。",
        "operationId": "【资产研判】Icon Hash 匹配",
        "parameters": [
          {
            "name": "url",
            "in": "query",
            "description": "要检查的网站的完整 URL (例如: https://www.example.com)。",
            "required": true,
            "schema": {
              "type": "string",
              "format": "url"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Favicon 哈希匹配结果",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "result": {
                      "type": "integer",
                      "description": "如果 Favicon 哈希值匹配成功，返回 100；否则返回 0。当发生网络错误或无法获取 Favicon 时也返回 0。",
                      "example": 100
                    },
                    "error": {
                      "type": "string",
                      "description": "当请求失败时，可能包含错误信息。",
                      "nullable": true,
                      "example": "Invalid URL"
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "请求参数错误",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string",
                      "description": "错误信息，例如 ''Missing \"url\" parameter''。",
                      "example": "Missing ''url'' parameter"
                    }
                  }
                }
              }
            }
          }
        },
        "deprecated": false
      }
    }
  },
  "components": {
    "schemas": {}
  }
}','openapi','8b3128aa-cf5a-47c7-be68-fee8bcec51f7'::uuid,'5a1eb0a8-9ccf-4a4a-9101-7d6273ee5bb3'::uuid,'[{"server_url": "http://192.168.31.92:11003/check_favicon", "method": "get", "summary": "\u83b7\u53d6\u6307\u5b9a URL \u7684 Favicon \u54c8\u5e0c\u5339\u914d\u7ed3\u679c\u3002\u8be5 API \u4f1a\u5c1d\u8bd5\u8bbf\u95ee /favicon.ico \u548c /assets/images/favicon.ico \u8def\u5f84\u3002", "operation_id": "\u3010\u8d44\u4ea7\u7814\u5224\u3011Icon Hash \u5339\u914d", "parameters": [{"name": "url", "label": {"en_US": "url", "zh_Hans": "url", "pt_BR": "url", "ja_JP": "url"}, "placeholder": {"en_US": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "zh_Hans": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "pt_BR": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "ja_JP": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002"}, "scope": null, "auto_generate": null, "template": null, "required": true, "default": null, "min": null, "max": null, "precision": null, "options": [], "type": "string", "human_description": {"en_US": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "zh_Hans": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "pt_BR": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "ja_JP": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002"}, "form": "llm", "llm_description": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002"}], "author": "", "icon": null, "openapi": {"description": "\u83b7\u53d6\u6307\u5b9a URL \u7684 Favicon \u54c8\u5e0c\u5339\u914d\u7ed3\u679c\u3002\u8be5 API \u4f1a\u5c1d\u8bd5\u8bbf\u95ee /favicon.ico \u548c /assets/images/favicon.ico \u8def\u5f84\u3002", "operationId": "\u3010\u8d44\u4ea7\u7814\u5224\u3011Icon Hash \u5339\u914d", "parameters": [{"name": "url", "in": "query", "description": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "required": true, "schema": {"type": "string", "format": "url"}}], "responses": {"200": {"description": "Favicon \u54c8\u5e0c\u5339\u914d\u7ed3\u679c", "content": {"application/json": {"schema": {"type": "object", "properties": {"result": {"type": "integer", "description": "\u5982\u679c Favicon \u54c8\u5e0c\u503c\u5339\u914d\u6210\u529f\uff0c\u8fd4\u56de 100\uff1b\u5426\u5219\u8fd4\u56de 0\u3002\u5f53\u53d1\u751f\u7f51\u7edc\u9519\u8bef\u6216\u65e0\u6cd5\u83b7\u53d6 Favicon \u65f6\u4e5f\u8fd4\u56de 0\u3002", "example": 100}, "error": {"type": "string", "description": "\u5f53\u8bf7\u6c42\u5931\u8d25\u65f6\uff0c\u53ef\u80fd\u5305\u542b\u9519\u8bef\u4fe1\u606f\u3002", "nullable": true, "example": "Invalid URL"}}}}}}, "400": {"description": "\u8bf7\u6c42\u53c2\u6570\u9519\u8bef", "content": {"application/json": {"schema": {"type": "object", "properties": {"error": {"type": "string", "description": "\u9519\u8bef\u4fe1\u606f\uff0c\u4f8b\u5982 ''Missing \"url\" parameter''\u3002", "example": "Missing ''url'' parameter"}}}}}}}, "deprecated": false}}]','{"content": "\ud83d\udd75\ufe0f", "background": "#FEF7C3"}','{"auth_type": "none"}','通过计算网站的 favicon.ico 哈希值，判断其是否与预设的目标哈希值匹配。这可以用于识别特定技术栈或网站特征。','2025-08-28 09:03:08','2025-08-28 09:03:08',NULL,''),
	 ('e0068a82-c175-466c-a80d-acde640b9fd1'::uuid,'【资产研判】Rawl4AI 网页爬虫 20250807','{
