            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "markdown": {
                      "type": "string",
                      "description": "Webpage content in Markdown format"
                    }
                  }
                }
              }
            }
          },
          "400": {
