                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": false
                    },
                    "error": {
                      "type": "string",
                      "example": "Missing ''url'' parameter"
                    }
                  }
                }
              }
            }
          },
          "500": {
            "description": "Server error during crawling",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": false
                    },
                    "error": {
                      "type": "string",
                      "example": "Failed to connect to the webpage"
                    }
                  }
                }
              }
            }
          }
        },
        "deprecated": false
      }
    }
  },
  "components": {
    "schemas": {}
  }
}','openapi','8b3128aa-cf5a-47c7-be68-fee8bcec51f7'::uuid,'5a1eb0a8-9ccf-4a4a-9101-7d6273ee5bb3'::uuid,'[{"server_url": "http://192.168.31.92:11001/crawl", "method": "post", "summary": "crawl4ai\u7f51\u9875\u722c\u866b", "operation_id": "\u3010\u8d44\u4ea7\u7814\u5224\u3011Rawl4AI \u7f51\u9875\u722c\u866b", "parameters": [{"name": "url", "label": {"en_US": "url", "zh_Hans": "url", "pt_BR": "url", "ja_JP": "url"}, "placeholder": {"en_US": "", "zh_Hans": "", "pt_BR": "", "ja_JP": ""}, "scope": null, "auto_generate": null, "template": null, "required": true, "default": null, "min": null, "max": null, "precision": null, "options": [], "type": "string", "human_description": {"en_US": "", "zh_Hans": "", "pt_BR": "", "ja_JP": ""}, "form": "llm", "llm_description": ""}], "author": "", "icon": null, "openapi": {"description": "crawl4ai\u7f51\u9875\u722c\u866b", "operationId": "\u3010\u8d44\u4ea7\u7814\u5224\u3011Rawl4AI \u7f51\u9875\u722c\u866b", "requestBody": {"description": "URL of the webpage to crawl", "required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"url": {"type": "string", "format": "uri", "example": "https://geekdaxue.co/read/Firecrawl/advanced-scraping-guide"}}, "required": ["url"]}}}}, "responses": {"200": {"description": "Successfully crawled webpage content", "content": {"application/json": {"schema": {"type": "object", "properties": {"success": {"type": "boolean", "example": true}, "markdown": {"type": "string", "description": "Webpage content in Markdown format"}}}}}}, "400": {"description": "Invalid request (missing or invalid URL)", "content": {"application/json": {"schema": {"type": "object", "properties": {"success": {"type": "boolean", "example": false}, "error": {"type": "string", "example": "Missing ''url'' parameter"}}}}}}, "500": {"description": "Server error during crawling", "content": {"application/json": {"schema": {"type": "object", "properties": {"success": {"type": "boolean", "example": false}, "err