28\u51fd\u6570\u6e90\u4ee3\u7801\u4fe1\u606f\n\n# \u62a5\u544a\u5e94\u6db5\u76d6\u4ee5\u4e0b\u5173\u952e\u5185\u5bb9\uff1a\n1. \u7f3a\u9677\u5f71\u54cd\u5206\u6790\uff1a\u8bf7\u8be6\u7ec6\u5206\u6790\u6b64\u7f3a\u9677\u5bf9\u7cfb\u7edf\u7684\u6f5c\u5728\u5f71\u54cd\uff0c\u5305\u62ec\u53ef\u80fd\u88ab\u653b\u51fb\u8005\u5229\u7528\u7684\u65b9\u5f0f\u3001\u5bf9\u7cfb\u7edf\u5b89\u5168\u6027\u548c\u6570\u636e\u5b8c\u6574\u6027\u7684\u5177\u4f53\u5a01\u80c1\uff0c\u4ee5\u53ca\u53ef\u80fd\u5f15\u53d1\u7684\u540e\u679c\u3002\n2. \u6f5c\u5728\u8bef\u62a5\u8bc4\u4f30\uff1a\u8bf7\u6df1\u5165\u5206\u6790\u6b64\u7f3a\u9677\u662f\u5426\u53ef\u80fd\u662f\u8bef\u62a5\u3002\u7ed3\u5408\u4ee3\u7801\u4e0a\u4e0b\u6587\u3001\u5b9e\u9645\u8fd0\u884c\u73af\u5883\u3001\u53d8\u91cf\u7684\u4f7f\u7528\u60c5\u51b5\u4ee5\u53ca\u65b9\u6cd5\u7684\u5177\u4f53\u529f\u80fd\uff0c\u8bc4\u4f30\u8bef\u62a5\u7684\u53ef\u80fd\u6027\u3002\u5982\u679c\u5b58\u5728\u8bef\u62a5\u7684\u5acc\u7591\uff0c\u8bf7\u660e\u786e\u8bf4\u660e\u539f\u56e0\uff0c\u5e76\u63d0\u4f9b\u8fdb\u4e00\u6b65\u9a8c\u8bc1\u6b64\u8bc4\u4f30\u7684\u5efa\u8bae\u3002\n3. \u6839\u672c\u539f\u56e0\u5206\u6790\uff1a\u8bf7\u786e\u5b9a\u5bfc\u81f4\u6b64\u7f3a\u9677\u7684\u6839\u672c\u539f\u56e0\uff0c\u8bf4\u660e\u4ee3\u7801\u4e2d\u5b58\u5728\u95ee\u9898\u7684\u5177\u4f53\u4f4d\u7f6e\u3001\u903b\u8f91\u9519\u8bef\u6216\u8bbe\u8ba1\u7f3a\u9677\uff0c\u5e76\u89e3\u91ca\u8fd9\u4e9b\u95ee\u9898\u662f\u5982\u4f55\u5f15\u53d1\u5b89\u5168\u6f0f\u6d1e\u7684\u3002\n4. \u4fee\u590d\u5efa\u8bae\uff08\u6700\u4f73\u4fee\u590d\u70b9\uff09\uff1a\u8bf7\u63d0\u4f9b\u8be6\u7ec6\u7684\u4fee\u590d\u63aa\u65bd\uff0c\u5305\u62ec\u4ee3\u7801\u66f4\u6b63\u65b9\u6cd5\u3001\u8f93\u5165\u9a8c\u8bc1\u7684\u6539\u8fdb\u3002\u540c\u65f6\uff0c\u5efa\u8bae\u6700\u4f73\u7684\u4fee\u590d\u4f4d\u7f6e\uff0c\u4ee5\u786e\u4fdd\u4fee\u590d\u7684\u6709\u6548\u6027\u548c\u5b8c\u6574\u6027\u3002\n5. \u5b89\u5168\u6700\u4f73\u5b9e\u8df5\uff1a\u5728\u6b64\u57fa\u7840\u4e0a\uff0c\u8bf7\u4e3