tion": "left", "type": "custom", "width": 244}, {"data": {"answer": "{{#1754550840849.text#}}", "desc": "", "selected": false, "title": "\u6f0f\u6d1e\u4fe1\u606f\u56de\u590d", "type": "answer", "variables": []}, "height": 105, "id": "1754549362248", "position": {"x": 1665.9712216378655, "y": -94.28274531498539}, "positionAbsolute": {"x": 1665.9712216378655, "y": -94.28274531498539}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"context": {"enabled": false, "variable_selector": []}, "desc": "", "model": {"completion_params": {"max_tokens": 20480, "temperature": 0.7}, "mode": "chat", "name": "SecGPT", "provider": "langgenius/xinference/xinference"}, "prompt_template": [{"id": "43ec5093-4151-4695-a9c9-aaea37a1d482", "role": "system", "text": "# \u89d2\u8272\n\u4f60\u662f\u4e00\u4e2a\u5b89\u5168\u4e13\u5bb6\uff0c\u6839\u636e\u7528\u6237\u7684\u95ee\u9898{{#sys.query#}}\uff0c\u4ee5markdown\u7684\u5f62\u5f0f\u8fdb\u884c\u56de\u7b54\uff0c\u4e00\u65e6\u53d1\u73b0\u6709\u4ee3\u7801\u90e8\u5206\u8f93\u51fa\u4ee3\u7801\n# \u7ea6\u675f\u6761\u4ef6\n- \u4ec5\u8ba8\u8bba\u4e0e\u6f0f\u6d1e\u4fe1\u606f\u76f8\u5173\u7684\u8bdd\u9898\u3002\n- \u4f7f\u7528\u4e2d\u6587\u56de\u7b54\u95ee\u9898"}], "selected": false, "title": "\u672a\u68c0\u7d22\u5230\u6f0f\u6d1e\u6570\u636e\u603b\u7ed3", "type": "llm", "variables": [], "vision": {"enabled": false}}, "height": 96, "id": "1754549686816", "position": {"x": 1068.9875842196984, "y": 130.46866457732702}, "positionAbsolute": {"x": 1068.9875842196984, "y": 130.46866457732702}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"answer": "\u8be5\u4fe1\u606f\u77e5\u8bc6\u5e93\u4e2d\u6682\u672a\u6536\u5f55\uff0c\u6211\u5c06\u7ed3\u5408\u6211\u7684\u77e5\u8bc6\u7ed9\u60a8\u56de\u7b54\u3002\n{{#1754549686816.text#}}", "desc": "", "selected": false, "title": "\u672a\u68c0\u7d22\u5230\u6f0f\u6d1e\u4fe1\u606f\u56de\u590d", "type": "answer", "variables": []}, "height": 137, "id": "1754549722384", "position": {"x": 1453.7389941120107, "y": 123.25871726551341}, "positionAbsolute": {"x": 1453.7389941120107, "y": 123.25871726551341}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"code": "import json\n\ndef main(vul_info: str) -> dict:\n    data = json.loads(vul_info)\n\n    # \u5b57\u6bb5\u6620\u5c04\n    vul_info_mapping = {\n        \"vul_id\": \"\u6f0f\u6d1e\u7f16\u53f7\",\n        \"cve_id\": \"CVE\u7f16\u53f7\",\n        \"cnvd_id\": \"CNVD\u7f16\u53f7\",\n        \"cnnvd_id\": \"CNNVD\u7f16\u53f7\",\n        \"title_cn\": \"\u6f0f\u6d1e\u6807\u9898\",\n        \"description_cn\": \"\u6f0f\u6d1e\u63cf\u8ff0_cn\",\n        \"description_en\": \"\u6f0f\u6d1e\u63cf\u8ff0_en\",\n        \"cvss2_base_score\": \"CVSS 2.0\u5206\u6570\",\n        \"cvss3_base_score\": \"CVSS 3.0\u5206\u6570\",\n        \"severity\": \"\u5371\u9669\u7b49\u7ea7\",\n        \"solution_cn\": \"\u4fee\u590d\u65b9\u6848_cn\",\n        \"solution_en\": \"\u4fee\u590d\u65b9\u6848_en\",\n        \"published_time\": \"\u53d1\u5e03\u65f6\u95f4\",\n        \"cwes\": \"\u5173\u8054CWE\"\n    }\n\n    severity_level_mapping = {\n        0: \"\u672a\u77e5\",\n        10: \"\u4f4e\u5371\",\n        20: \"\u4e2d\u5371\",\n        30: \"\u9ad8\u5371\",\n        40: \"\u8d85\u5371\"\n    }\n\n    vul_reference_mapping = {\n        \"source_type\": \"\u53c2\u8003\u6765\u6e90\",\n        \"url\": \"\u53c2\u8003\u94fe\u63a5\"\n    }\n\n    vul_relproduct_mapping = {\n        \"vendor\": \"\u5382\u5546\",\n        \"affect_product_name\": \"\u5f71\u54cd\u4ea7\u54c1\",\n        \"affected_version_expression\": \"\u5f71\u54cd\u7248\u672c\"\n    }\n\n    # \u4fee\u590d\uff1a\u4fdd\u7559\u7a7a\u5b57\u7b26\u4e32\u5b57\u6bb5\n    def translate_keys(d: dict, mapping: dict) -> dict:\n        result = {}\n        for k in mapping:\n            if k in d and (d[k] is not None or d[k] == \"\"):\n                result[mapping[k]] = d[k]\n        return result\n\n    # 1. \u6e05\u6d17\u6f0f\u6d1e\u4fe1\u606f\n    base_info = translate_keys(data.get(\"vul_info\", {}), vul_info_mapping)\n\n    # 2. \u5371\u9669\u7b49\u7ea7 severity \u8f6c\u6362\u4e3a\u4e2d\u6587\u7b49\u7ea7\n    if \"\u5371\u9669\u7b49\u7ea7\" in base_info:\n        score = base_info[\"\u5371\u9669\u7b49\u7ea7\"]\n        base_info[\"\u5371\u9669\u7b49\u7ea7\"] = severity_level_mapping.get(score, f\"\u672a\u77e5\uff08{score}\uff09\")\n\n    # 3. \u6e05\u6d17\u5e76\u6574\u5408\u53c2\u8003\u94fe\u63a5\n    reference_list = [\n        translate_keys(ref, vul_reference_mapping)\n        for ref in data.get(\"vul_reference\", [])\n        if translate_keys(ref, vul_reference_mapping)\n    ]\n    if reference_list:\n        base_info[\"\u53c2\u8003\u94fe\u63a5\u4fe1\u606f\"] = reference_list\n\n    # 4. \u6e05\u6d17\u5e76\u6574\u5408\u5f71\u54cd\u4ea7\u54c1\n    product_list = [\n        translate_keys(prod, vul_relproduct_mapping)\n        for prod in data.get(\"vul_relproduct\", [])\n        if translate_keys(prod, vul_relproduct_mapping)\n    ]\n    if product_list:\n        base_info[\"\u5f71\u54cd\u4ea7\u54c1\u4fe1\u606f\"] = product_list\n\n    return {\n        \"result\": str(base_info)\n    }", "code_language": "python3", "desc": "", "outputs": {"result": {"children": null, "type": "string"}}, "selected": false, "title": "\u6f0f\u6d1e\u6570\u636e\u6e05\u6d17", "type": "code", "variables": [{"value_selector": ["1754549257434", "body"], "variable": "vul_info"}]}, "height": 54, "id": "1754549981717", "position": {"x": 1012.7499951875523, "y": 13.866464362218778}, "positionAbsolute": {"x": 1012.7499951875523, "y": 13.866464362218778}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"context": {"enabled": true, "variable_selector": ["1754549981717", "result"]}, "desc": "", "model": {"completion_params": {