	 ('48f023e4-44a0-477a-b718-6ada4fb004fe'::uuid,'5a1eb0a8-9ccf-4a4a-9101-7d6273ee5bb3'::uuid,'cffd0195-5924-468e-b642-1c3c0d12784a'::uuid,'workflow','2025-08-28 09:17:34.719123','{"nodes": [{"data": {"desc": "https://www.baidu.com", "selected": false, "title": "\u5f00\u59cb", "type": "start", "variables": [{"label": "url", "max_length": null, "options": [], "required": true, "type": "text-input", "variable": "url"}]}, "height": 118, "id": "1724639372563", "position": {"x": -526.1942144267209, "y": 253}, "positionAbsolute": {"x": -526.1942144267209, "y": 253}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"code": "import json\nimport re\n\ndef clean_markdown(text: str) -> str:\n    if not text:\n        return \"\"\n    \n    # 1. \u79fb\u9664\u6240\u6709 URL\uff08http, https, javascript\uff09\n    text = re.sub(r''(https?://[^\\s\"\\''\\\\\\]\\)]+|javascript:[^\\s\"\\''\\\\\\]\\)]+)'', '''', text)\n\n    # 2. \u53bb\u6389 Markdown \u4e2d base64 \u56fe\u7247\u8bed\u6cd5 ![alt](data:image/...)\n    text = re.sub(r''!\\[.*?\\]\\(data:image\\/[a-zA-Z]+;base64,[^\\)]*?\\)'', '''', text)\n\n    # 3. \u53bb\u6389 Markdown \u56fe\u7247\u8bed\u6cd5 ![alt](url)\n    text = re.sub(r''!\\[.*?\\]\\(.*?\\)'', '''', text)\n\n    # 4. \u53bb\u6389 Markdown \u94fe\u63a5 [text](url) \u2192 \u53ea\u4fdd\u7559 text\n    text = re.sub(r''\\[([^\\]]+)\\]\\(.*?\\)'', r''\\1'', text)\n\n    # 5. \u79fb\u9664 HTML \u4e2d base64 \u56fe\u7247\u6807\u7b7e\n    text = re.sub(r''<img\\s+[^>]*src=[\"\\'']data:image\\/[a-zA-Z]+;base64,[^\"\\'']*[\"\\''][^>]*>'', '''', text, flags=re.IGNORECASE)\n\n    # 6. \u79fb\u9664 HTML \u6807\u7b7e\n    text = re.sub(r''<[^>]+>'', '''', text)\n\n    # 7. \u6e05\u7406\u591a\u4f59\u7684\u6362\u884c\u548c\u7a7a\u683c\n    text = re.sub(r''\\n+'', ''\\n'', text)  # \u5408\u5e76\u591a\u884c\u6362\u884c\u7b26\n    text = re.sub(r''\\s{2,}'', '' '', text)  # \u5408\u5e76\u591a\u4f59\u7a7a\u683c\n  