ext = arg\n\n    # 1. \u79fb\u9664\u6240\u6709 URL\uff08http, https, javascript\uff09\n    text = re.sub(r''(https?://[^\\s\"\\''\\\\\\]\\)]+|javascript:[^\\s\"\\''\\\\\\]\\)]+)'', '''', text)\n\n    # 2. \u53bb\u6389 Markdown \u56fe\u7247\u8bed\u6cd5 ![alt](url)\n    text = re.sub(r''!\\[.*?\\]\\(.*?\\)'', '''', text)\n\n    # 3. \u53bb\u6389 Markdown \u94fe\u63a5 [text](url) \u2192 \u53ea\u4fdd\u7559 text\n    text = re.sub(r''\\[([^\\]]+)\\]\\(.*?\\)'', r''\\1'', text)\n\n    # 4. \u79fb\u9664 HTML \u6807\u7b7e\n    text = re.sub(r''<[^>]+>'', '''', text)\n\n    # 5. \u6e05\u7406\u591a\u4f59\u7684\u6362\u884c\u548c\u7a7a\u683c\n    text = re.sub(r''\\n+'', ''\\n'', text)  # \u5408\u5e76\u591a\u884c\u6362\u884c\u7b26\n    text = re.sub(r''\\s{2,}'', '' '', text)  # \u5408\u5e76\u591a\u4f59\u7a7a\u683c\n    text = text.strip()\n\n    return {\n        \"result\": text\n    }", "code_language": "python3", "desc": "", "outputs": {"result": {"children": null, "type": "string"}}, "selected": false, "title": "\u4ee3\u7801\u6267\u884c 3", "type": "code", "variables": [{"value_selector": ["1724654533265", "body"], "variable": "arg"}]}, "height": 54, "id": "1745214230128", "position": {"x": 72.48668718236269, "y": 253}, "positionAbsolute": {"x": 72.48668718236269, "y": 253}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}], "edges": [{"data": {"isInIteration": false, "sourceType": "start", "targetType": "http-request"}, "id": "1724639372563-source-1724654533265-target", "source": "1724639372563", "sourceHandle": "source", "target": "1724654533265", "targetHandle": "target", "type": "custom", "zIndex": 0}, {"data": {"isInIteration": false, "sourceType": "code", "targetType": "llm"}, "id": "1724653169366-source-1727230011834-target", "source": "1724653169366", "sourceHandle": "source", "target": "1727230011834", "targetHandle": "target", "type": "custom", "zIndex": 0}, {"data": {"isInIteration": false, "sourceType": "ll