"variables": []}, "height": 137, "id": "1754549722384", "position": {"x": 1453.7389941120107, "y": 123.25871726551341}, "positionAbsolute": {"x": 1453.7389941120107, "y": 123.25871726551341}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"code": "import json\n\ndef main(vul_info: str) -> dict:\n    data = json.loads(vul_info)\n\n    # \u5b57\u6bb5\u6620\u5c04\n    vul_info_mapping = {\n        \"vul_id\": \"\u6f0f\u6d1e\u7f16\u53f7\",\n        \"cve_id\": \"CVE\u7f16\u53f7\",\n        \"cnvd_id\": \"CNVD\u7f16\u53f7\",\n        \"cnnvd_id\": \"CNNVD\u7f16\u53f7\",\n        \"title_cn\": \"\u6f0f\u6d1e\u6807\u9898\",\n        \"description_cn\": \"\u6f0f\u6d1e\u63cf\u8ff0_cn\",\n        \"description_en\": \"\u6f0f\u6d1e\u63cf\u8ff0_en\",\n        \"cvss2_base_score\": \"CVSS 2.0\u5206\u6570\",\n        \"cvss3_base_score\": \"CVSS 3.0\u5206\u6570\",\n        \"severity\": \"\u5371\u9669\u7b49\u7ea7\",\n        \"solution_cn\": \"\u4fee\u590d\u65b9\u6848_cn\",\n        \"solution_en\": \"\u4fee\u590d\u65b9\u6848_en\",\n        \"published_time\": \"\u53d1\u5e03\u65f6\u95f4\",\n        \"cwes\": \"\u5173\u8054CWE\"\n    }\n\n    severity_level_mapping = {\n        0: \"\u672a\u77e5\",\n        10: \"\u4f4e\u5371\",\n        20: \"\u4e2d\u5371\",\n        30: \"\u9ad8\u5371\",\n        40: \"\u8d85\u5371\"\n    }\n\n    vul_reference_mapping = {\n        \"source_type\": \"\u53c2\u8003\u6765\u6e90\",\n        \"url\": \"\u53c2\u8003\u94fe\u63a5\"\n    }\n\n    vul_relproduct_mapping = {\n        \"vendor\": \"\u5382\u5546\",\n        \"affect_product_name\": \"\u5f71\u54cd\u4ea7\u54c1\",\n        \"affected_version_expression\": \"\u5f71\u54cd\u7248\u672c\"\n    }\n\n    # \u4fee\u590d\uff1a\u4fdd\u7559\u7a7a\u5b57\u7b26\u4e32\u5b57\u6bb5\n    def translate_keys(d: dict, mapping: dict) -> dict:\n        result = {}\n        for k in mapping:\n            if k in d and (d[k] is not None or d[k] == \"\"):\n                result[mapping[k]] = d[k]\n        return result\n\n    # 1. \u6e05\u6d17\u6f0f\u6d1e\u4fe1\u606f\n    base_info = translate_keys(data.get(\"vul_info\", {}), vul_info_mapping)\n\n    # 2. \u5371\u9669\u7b49\u7ea7 severity \u8f6c\u6362\u4e3a\u4e2d\u6587\u7b49\u7ea7\n    if \"\u5371\u9669\u7b49\u7ea7\" in base_info:\n        score = base_info[\"\u5371\u9669\u7b49\u7ea7\"]\n        base_info[\"\u5371\u9669\u7b49\u7ea7\"] = severity_level_mapping.get(score, f\"\u672a\u77e5\uff08{score}\uff09\")\n\n    # 3. \u6e05\u6d17\u5e76\u6574\u5408\u53c2\u8003\u94fe\u63a5\n    reference_list = [\n        translate_keys(ref, vul_reference_mapping)\n        for ref in data.get(\"vul_reference\", [])\n        if translate_keys(ref, vul_reference_mapping)\n    ]\n    if reference_list:\n        base_info[\"\u53c2\u8003\u94fe\u63a5\u4fe1\u606f\"] = reference_list\n\n    # 4. \u6e05\u6d17\u5e76\u6574\u5408\u5f71\u54cd\u4ea7\u54c1\n    product_list = [\n        translate_keys(prod, vul_relproduct_mapping)\n        for prod in data.get(\"vul_relproduct\", [])\n        if translate_keys(prod, vul_relproduct_mapping)\n    ]\n    if product_list:\n        base_info[\"\u5f71\u54cd\u4ea7\u54c1\u4fe1\u606f\"] = product_list\n\n    return {\n        \"result\": str(base_info)\n    }", "code_language": "python3", "desc": "", "outputs": {"result": {"children": null, "type": "string"}}, "selected": false, "title": "\u6f0f\u6d1e\u6570\u636e\u6e05\u6d17", "type": "code", "variables": [{"value_selector": ["1754549257434", "body"], "variable": "vul_info"}]}, "height": 54, "id": "1754549981717", "position": {"x": 1012.7499951875523, "y": 13.866464362218778}, "positionAbsolute": {"x": 1012.7499951875523, "y": 13.866464362218778}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"context": {"enabled": true, "variable_selector": ["1754549981717", "result"]}, "desc": "", "model": {"completion_params": {"max_tokens": 20480, 