1002}, {"data": {"code": "\ndef main(address: str) -> dict:\n    return {\n        \"result\": {\n            \"address\": address,\n            \"correlation\": 1,\n            \"summary\": \"\u8be5\u8d44\u4ea7\u662f\u56fd\u5bb6\u7535\u7f51\u516c\u53f8\u7684\u5185\u90e8\u5730\u5740\uff0c\u7528\u4e8e\u652f\u6491\u7535\u529b\u8c03\u5ea6\u548c\u6570\u636e\u4f20\u8f93\u4e1a\u52a1\",\n            \"confidence_degree\": 100,\n            \"according\": \"\u76ee\u6807\u8d44\u4ea7\u5b58\u5728\u4e8e\u5df2\u77e5\u7684\u56fd\u7f51IP\u8d44\u4ea7\u5217\u8868\u4e2d\",\n            \"tags\": [\n                \"\u7535\u529b\u670d\u52a1\",\n                \"\u5185\u90e8IP\",\n                \"\u56fd\u7f51\"\n            ]\n        },\n    }\n", "code_language": "python3", "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "outputs": {"result": {"children": null, "type": "object"}}, "selected": false, "title": "\u5185\u90e8\u8d44\u4ea7\u8f93\u51fa", "type": "code", "variables": [{"value_selector": ["1753520887044", "item"], "variable": "address"}]}, "height": 54, "id": "1753520923161", "parentId": "1753520887044", "position": {"x": 2940, "y": 109}, "positionAbsolute": {"x": 4471.142857142857, "y": 813.4285714285716}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244, "zIndex": 1002}, {"data": {"code": "\ndef main(data: list[str], taskId: str) -> dict:\n    return {\n        \"result\": {\n            \"taskId\": taskId,\n            \"data\": data\n        }\n    }\n", "code_language": "python3", "desc": "", "outputs": {"result": {"children": null, "type": "object"}}, "selected": false, "title": "\u7814\u5224\u7ed3\u679c\u5904\u7406", "type": "code", "variables": [{"value_selector": ["1753520447283", "output"], "variable": "data"}, {"value_selector": ["1753517223628", "taskId"], "variable": "taskId"}]}, "height": 54, "id": "1753521109577", "position": {"x": 5766, "y": 749}, "positionAbsolute": {"x": 5766, "y": 749}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"code": "import re\n\ndef main(url_or_ip: str) -> dict:\n    # \u6539\u8fdb\u7684\u6b63\u5219\u8868\u8fbe\u5f0f\uff0c\u80fd\u591f\u6355\u83b7\u4e3b\u673a\u540d\u4e4b\u540e\u7684\u8def\u5f84\u3001\u67e5\u8be2\u53c2\u6570\u548c\u7247\u6bb5\n    m = re.match(\n        r''^(https?://)?''                       # 1 \u534f\u8bae(\u53ef\u9009)\n        r''((?:\\[[0-9a-fA-F:]+\\]|''              #   2 host \u5f00\u59cb\n        r''(?:\\d{1,3}\\.){3}\\d{1,3}|''\n        r''[^/:?#]+)''\n        r''(?::\\d+)?)''                          #   \u7aef\u53e3(\u53ef\u9009) host \u7ed3\u675f\n        r''(.*)'',                               # 3 \u8def\u5f84\u3001\u67e5\u8be2\u53c2\u6570\u548c\u7247\u6bb5(\u53ef\u9009)\n        url_or_ip\n    )\n\n    if not m:\n        # \u515c\u5e95\uff1a\u65e0\u6cd5\u89e3\u6790\u5219\u539f\u6837\u8fd4\u56de\n        return {\"true_target\": url_or_ip}\n\n    proto = m.group(1) or \"http://\"            # \u65e0\u534f\u8bae\u65f6\u8865 http://\n    host  = m.group(2)                         # \u7eaf host(+\u7aef\u53e3)\n    path  = m.group(3)                         # \u8def\u5f84\u90e8\u5206\n    \n    # \u7ec4\u5408\u5404\u90e8\u5206\uff0c\u4fdd\u7559\u539f\u59cb\u8def\u5f84\n    return {\"true_target\": f\"{proto}{host}{path}\"}\n", "code_language": "python3", "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "outputs": {"true_target": {"children": null, "type": "string"}}, "selected": false, "title": "\u683c\u5f0f\u5316\u5730\u5740", "type": "code", "variables": [{"value_selector": ["1753520887044", "item"], "variable": "url_or_ip"}]}, "height": 54, "id": "1753521895768", "parentId": "1753520887044", "position": {"x": 204, "y": 109}, "positionAbsolute": {"x": 1735.1428571428569, "y": 813.4285714285716}, "selected": false, "sourcePosition": "right", "targetPosition": "left