u7ef4\u5ea6\u3001\u4e1a\u52a1\u6807\u8bc6\u7ef4\u5ea6\uff08\u5982\u62db\u8058/\u5408\u4f5c\u4fe1\u606f\uff09\uff0c\u8ba1\u7b97\u65f6\u6807\u9898\u7ef4\u5ea6\u6743\u91cd\uff1e\u57df\u540d\u7ef4\u5ea6\uff1e\u4e1a\u52a1\u6807\u8bc6\u7ef4\u5ea6\uff1e\u7f51\u9875\u5185\u5bb9\u7ef4\u5ea6\uff08\u5185\u5bb9\u6613\u542b\u65e0\u5173\u4fe1\u606f\uff09\u3002\n\n\n### \u6838\u5fc3\u5224\u5b9a\u89c4\u5219\uff1a\n1. **\u76f8\u5173\u6027\u5224\u5b9a**\uff1a\n   - \u5b58\u5728\u4efb\u4e00\u652f\u8def\u6743\u91cd\u4e0d\u4e3a0\uff08\u6743\u91cd\u6c47\u603b\u22600\uff09\u2192 correlation=1\uff08\u76f8\u5173\u8d44\u4ea7\uff09\uff1b\n   - \u6240\u6709\u652f\u8def\u6743\u91cd\u5747\u4e3a0\uff08\u6743\u91cd\u6c47\u603b=0\uff09\u2192 correlation=2\uff08\u65e0\u5173\u8d44\u4ea7\uff09\uff1b\n   - \u65e0\u6cd5\u8bbf\u95ee\u6216\u9875\u9762\u51fa\u73b0404\u3001400\u3001500\u7b49\u5185\u5bb9 \u2192 correlation=3\u3002\n\n2. **\u7f6e\u4fe1\u5ea6\u8ba1\u7b97\u903b\u8f91\uff08\u7ec6\u5316\u7ef4\u5ea6\u89c4\u5219\uff09**\uff1a\n   - **\u76f8\u5173\u8d44\u4ea7\uff08correlation=1\uff09**\uff1a\n     - \u7ef4\u5ea6\u5224\u5b9a\uff1a\u9700\u660e\u786e\u533a\u5206\u6807\u9898/\u57df\u540d/\u5185\u5bb9/\u4e1a\u52a1\u6807\u8bc64\u7c7b\u7ef4\u5ea6\uff0c\u5355\u4e00\u7ef4\u5ea6\uff08\u4ec51\u7c7b\u6709\u503c\uff0c\u5176\u4ed63\u7c7b\u4e3a0/\u672a\u627e\u5230\uff0c\u4e14\u8be5\u7ef4\u5ea6\u6743\u91cd\u9ad8\u4e8e30\uff0c\u4e0d\u5305\u542b30\uff09\u2192 \u65e0\u8bba\u8be5\u7ef4\u5ea6\u6743\u91cd\u591a\u9ad8\uff0c\u7f6e\u4fe1\u5ea6\u226450\uff1b\n     - \u4e24\u4e2a\u7ef4\u5ea6\u6709\u503c\uff1a\u82e5\u542b\u6807\u9898/\u57df\u540d\u9ad8\u6743\u91cd\u7ef4\u5ea6\uff08\u226560\uff09\uff0c\u4e14\u53e6\u4e00\u7ef4\u5ea6\u6743\u91cd\u226530 \u2192 \u7f6e\u4fe1\u5ea660-70\uff1b\u82e5\u4ec5\u5185\u5bb9/\u4e1a\u52a1\u6807\u8bc6\u7ef4\u5ea6\u6709\u503c \u2192 \u7f6e\u4fe1\u5ea640-50\uff1b\n     - \u4e09\u4e2a\u53ca\u4ee5\u4e0a\u7ef4\u5ea6\u6709\u503c\uff1a\u7ef4\u5ea6\u8986\u76d6\u8d8a\u5168\u9762\uff08\u542b\u6807\u9898/\u57df\u540d\u7c7b\uff09\uff0c\u6743\u91cd\u603b\u548c\u8d8a\u9ad8 \u2192 \u7f6e\u4fe1\u5ea670-90\uff1b\u5168\u7ef4\u5ea6\u8986\u76d6\u4e14\u6807\u9898/\u57df\u540d\u6743\u91cd\u226580 \u2192 \u7f6e\u4fe1\u5ea690-100\uff1b\n     - \u7f51\u9875\u5185\u5bb9\u7ef4\u5ea6\u5355\u72ec\u6709\u503c\uff08\u5176\u4ed6\u7ef4\u5ea6\u65e0\uff09\u2192 \u5373\u4f7f\u6743\u91cd80+\uff0c\u7f6e\u4fe1\u5ea6\u226440\u3002\n   - **\u65e0\u5173\u8d44\u4ea7\uff08correlation=2\uff09**\uff1a\n     - \u591a\u7ef4\u5ea6\uff08\u22653\u7c7b\uff09\u5747\u4e3a0\uff0c\u6216\u660e\u786e\u542b\u975e\u56fd\u7f51\u7279\u5f81\uff08\u5982\u6559\u80b2\u673a\u6784/\u5176\u4ed6\u4f01\u4e1a\u6807\u8bc6\uff09\u2192 \u7f6e\u4fe1\u5ea680-100\uff1b\n     - \u4e2a\u522b\u7ef4\u5ea6\uff081-2\u7c7b\uff09\u6709\u4f4e\u6743\u91cd\u6a21\u7cca\u503c\uff08\uff1c30\uff09\u4f46\u6574\u4f53\u65e0\u5173 \u2192 \u7f6e\u4fe1\u5ea650-70\uff1b\n     - \u5355\u4e00\u7ef4\u5ea6\u4e3a0\u4e14\u5176\u4ed6\u7ef4\u5ea6\u7f3a\u5931\uff08\u65e0\u4fe1\u606f\uff09\u2192 \u7f6e\u4fe1\u5ea630-50\u3002\n\n\n\u8bf7\u6839\u636e\u4e0a\u8ff0\u89c4\u5219\u8f93\u51fa\u4ee5\u4e0b\u5b57\u6bb5\uff0c**\u4ec5\u8f93\u51faJSON\u7ed3\u6784\uff0c\u4e25\u683c\u7b26\u5408\u683c\u5f0f\uff0c\u65e0\u6ce8\u91ca\u3001markdown\u6216\u591a\u4f59\u89e3\u91ca**\uff1a\n```json\n{\n  \"address\": \"\u63d0\u53d6\u7684\u8d44\u4ea7IP\u6216\u57df\u540d\uff0c\u4f7f\u7528<target>\u7684\u771f\u5b9e\u503c\",\n  \"correlation\": 1/2/3,  // 1=\u76f8\u5173\uff0c2=\u65e0\u5173\uff0c3=\u65e0\u6cd5\u8bbf\u95ee\n  \"summary\": \"\u7ea650\u5b57\u63cf\u8ff0\u8d44\u4ea7\u7528\u9014\u3001\u80cc\u666f\u6216\u5f52\u5c5e\",\n  \"confidence_degree\": 0~100\u7684\u6574\u6570\uff08\u4e0d\u5e26%\uff09,\n  \"tags\": [\n    \"\u6807\u7b7e1\uff086\u5b57\u4ee5\u5185\uff0c\u4f53\u73b0\u56fd\u7f51\u76f8\u5173\u7279\u5f81\uff09\",\n    \"\u6807\u7b7e2\uff086\u5b57\u4ee5\u5185\uff0c\u8865\u5145\u4e1a\u52a1\u5c5e\u6027\uff0c\u5982\u201c\u7535\u529b\u8c03\u5ea6\u201d\uff1b\u65e0\u5173\u8d44\u4ea7\u5219\u4f53\u73b0\u5176\u81ea\u8eab\u7279\u5f81\uff09\"\n  ],\n  \"according\": \"\u5224\u65ad\u7684\u5173\u952e\u5177\u4f53\u4f9d\u636e\uff0c\u4e0d\u8981\u51fa\u73b0\u4efb\u4f55\u6570\u503c\"\n}\n```"}], "selected": true, "structured_output": {"schema": {"additionalProperties": false, "properties": {"address": {"description": "\u8d44\u4ea7", "type": "string"}, "correlation": {"description": "\u662f\u5426\u76f8\u5173", "enum": ["1", "2", "3"], "type": "number"}}, "required": [], "type": "object"}}, "structured_output_enabled": false, "title": "\u76f8\u4f3c\u5ea6\u5339\u914d", "type": "llm", "variables": [], "vision": {"enabled": false}}, "height": 132, "id": "1753526606460", "parentId": "1753520887044", "position": {"x": 2628, "y": 261.1428571428571}, "positionAbsolute": {"x": 4159.142857142857, "y": 965.5714285714287}, "selected": true, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244, "zIndex": 1002}, {"data": {"code": "import json\nimport re\n\ndef main(arg1: str, address: str) -> dict:\n    # \u53bb\u6389 markdown \u6807\u8bb0\u548c\u591a\u4f59\u53cd\u5f15\u53f7\n    cleaned = re.sub(r\"^`+json|`+$\", \"\", arg1.strip(), flags=re.IGNORECASE).strip()\n\n    # \u89e3\u6790\u4e3a\u5b57\u5178\u5bf9\u8c61\n    try:\n        result_data = json.loads(cleaned)\n    except Exception as e:\n        # \u8fd4\u56de\u7814\u5224\u5931\u8d25\u4fe1\u606f\n        result_data = {\n            \"address\": address,\n            \"correlation\": 5,\n            \"summary\": \"\u7814\u5224\u5931\u8d25\uff0c\u6a21\u578b\u8f93\u51fa\u683c\u5f0f\u9519\u8bef\",\n            \"confidence_degree\": 0,\n            \"tags\": [\"\u7814\u5224\u5931\u8d25\"],\n            \"according\": f\"\u6a21\u578b\u8f93\u51fa\u65e0\u6cd5\u89e3\u6790: {str(e)}\"\n        }\n\n    return {\n        \"result\": result_data\n    }", "code_language": "python3", "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "outputs": {"result": {"children