49}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"code": "import re\n\ndef main(url_or_ip: str) -> dict:\n    # \u6539\u8fdb\u7684\u6b63\u5219\u8868\u8fbe\u5f0f\uff0c\u80fd\u591f\u6355\u83b7\u4e3b\u673a\u540d\u4e4b\u540e\u7684\u8def\u5f84\u3001\u67e5\u8be2\u53c2\u6570\u548c\u7247\u6bb5\n    m = re.match(\n        r''^(https?://)?''                       # 1 \u534f\u8bae(\u53ef\u9009)\n        r''((?:\\[[0-9a-fA-F:]+\\]|''              #   2 host \u5f00\u59cb\n        r''(?:\\d{1,3}\\.){3}\\d{1,3}|''\n        r''[^/:?#]+)''\n        r''(?::\\d+)?)''                          #   \u7aef\u53e3(\u53ef\u9009) host \u7ed3\u675f\n        r''(.*)'',                               # 3 \u8def\u5f84\u3001\u67e5\u8be2\u53c2\u6570\u548c\u7247\u6bb5(\u53ef\u9009)\n        url_or_ip\n    )\n\n    if not m:\n        # \u515c\u5e95\uff1a\u65e0\u6cd5\u89e3\u6790\u5219\u539f\u6837\u8fd4\u56de\n        return {\"true_target\": url_or_ip}\n\n    proto = m.group(1) or \"http://\"            # \u65e0\u534f\u8bae\u65f6\u8865 http://\n    host  = m.group(2)                         # \u7eaf host(+\u7aef\u53e3)\n    path  = m.group(3)                         # \u8def\u5f84\u90e8\u5206\n    \n    # \u7ec4\u5408\u5404\u90e8\u5206\uff0c\u4fdd\u7559\u539f\u59cb\u8def\u5f84\n    return {\"true_target\": f\"{proto}{host}{path}\"}\n", "code_language": "python3", "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "outputs": {"true_target": {"children": null, "type": "string"}}, "selected": false, "title": "\u683c\u5f0f\u5316\u5730\u5740", "type": "code", "variables": [{"value_selector": ["1753520887044", "item"], "variable": "url_or_ip"}]}, "height": 54, "id": "1753521895768", "parentId": "1753520887044", "position": {"x": 204, "y": 109}, "positionAbsolute": {"x": 1735.1428571428569, "y": 813.4285714285716}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", 