        \"\u6000\u5b89\u4f9b\u7535\": 50,\n        \"\u6000\u6765\u4f9b\u7535\": 50,\n        \"\u6dbf\u9e7f\u4f9b\u7535\": 50,\n        \"\u8d64\u57ce\u4f9b\u7535\": 50,\n        \"\u56fa\u5b89\u4f9b\u7535\": 50,\n        \"\u8c03\u63a7\u4e2d\u5fc3OMS\": 60,\n        \"\u7528\u91c7\u7cfb\u7edf\": 20,\n        \"\u7535\u80fd\u8d28\u91cf\": 20,\n        \"\u8ba1\u91cf\u5e93\u7ba1\": 20,\n        \"\u7ebf\u635f\u7cfb\u7edf\": 40,\n        \"\u7528\u7535\u4fe1\u606f\": 20,\n        \"\u5168\u666f\u5e93\u623f\": 30,\n        \"\u62c6\u6bc1\u7535\u80fd\u8868\u5206\u62e3\": 50,\n        \"\u8d1f\u8377\u5206\u6790\": 30,\n        \"\u5468\u8f6c\u67dc\": 20,\n        \"\u5206\u5e03\u5f0f\u7535\u6e90\u529f\u7387\u9884\u6d4b\": 20,\n        \"\u7535\u80fd\u8d28\u91cf\u68c0\u6d4b\": 20,\n        \"\u8f93\u7535\u5168\u666f\": 30\n    }\n    \n    count = 0\n    \n    for word, value in word_values.items():\n        if word in arg1:\n            count += value\n    \n    return {\n        \"count\": count,\n    }\n   ", "code_language": "python3", "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "outputs": {"count": {"children": null, "type": "number"}}, "selected": false, "title": "\u8bcd\u6c47\u5339\u914d\uff08\u8ba1\u7b97\u76f8\u5173\u6027\uff09", "type": "code", "variables": [{"value_selector": ["1756371967537", "text"], "variable": "arg1"}]}, "height": 54, "id": "1753526157254", "parentId": "1753520887044", "position": {"x": 2028, "y": 448}, "positionAbsolute": {"x": 3559.142857142857, "y": 1152.4285714285716}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244, "zIndex": 1002}, {"data": {"code": "import json\n\ndef main(arg1: str, arg2: int, arg3: str, arg4: str) -> dict:\n    \"\"\"\n    \u6839\u636e\u8f93\u5165\u7684\u53c2\u6570\uff0c\u751f\u6210\u4e00\u4e2a\u5173\u4e8e\u7f51\u9875\u56fd\u7f51\u76f8\u5173\u4fe1\u606f\u7684\u8bc4\u4f30\u7ed3\u679c\u3002\n\n    Args:\n        arg1 (str): \u7f51\u9875\u4e2d\u5b58\u5728\u56fd\u7f51\u76f8\u5173\u7f51\u9875\u94fe\u63a5\u7684\u6743\u91cd\uff08JSON\u5b57\u7b26\u4e32\uff09\n        arg2 (int): \u7f51\u9875\u4e2d\u5b58\u5728\u56fd\u7f51\u76f8\u5173\u8bcd\u6c47\u7684\u6743\u91cd\n        arg3 (str): \u7f51\u9875icon\u4e3a\u56fd\u7f51\u56fe\u6807\u7684\u6743\u91cd\uff08JSON\u5b57\u7b26\u4e32\uff09\n        arg4 (str): \u7f51\u9875Title\u8bc4\u4f30\u7ed3\u679c\uff08JSON\u5b57\u7b26\u4e32\uff0c\u65b0\u683c\u5f0f\u5305\u542btotal_score\uff09\n\n    Returns:\n        dict: \u5305\u542b\u8bc4\u4f30\u7ed3\u679c\u7684\u5b57\u5178\uff0c\u683c\u5f0f\u4e3a {\"result\": \"\u6c47\u603b\u7ed3\u679c\u5b57\u7b26\u4e32\"}\u3002\n    \"\"\"\n    # \u89e3\u6790arg1\uff08\u7f51\u9875\u94fe\u63a5\u6743\u91cd\uff09\n    try:\n        arg1_json = json.loads(arg1)\n        arg1_data = arg1_json.get(\"result\", 0)\n        arg1 = int(arg1_data)\n    except (json.JSONDecodeError, ValueError):\n        arg1 = 0\n\n    # \u89e3\u6790arg3\uff08\u56fe\u6807\u6743\u91cd\uff09\n    try:\n        arg3_json = json.loads(arg3)\n        arg3_data = arg3_json.get(\"result\", 0)\n        arg3 = int(arg3_data)\n    except (json.JSONDecodeError, ValueError):\n        arg3 = 0\n\n    # \u89e3\u6790arg4\uff08\u6807\u9898\u6743\u91cd\uff09- \u9002\u914d\u65b0\u683c\u5f0f\uff0c\u4ecetotal_score\u83b7\u53d6\u503c\n    try:\n        arg4_json = json.loads(arg4)\n        # \u4ece\u65b0\u683c\u5f0f\u7684arg4\u4e2d\u63d0\u53d6total_score\u5b57\u6bb5\n        arg4_data = arg4_json.get(\"total_score\", 0)\n        arg4 = int(arg4_data)\n    except (json.JSONDecodeError, ValueError):\n        arg4 = 0\n\n    output_messages = []\n\n    # \u5904\u7406\u7f51\u9875\u94fe\u63a5\u6743\u91cd\n    if arg1 > 0:\n        output_messages.append(f\"\u7f51\u9875\u4e2d\u5b58\u5728\u56fd\u7f51\u76f8\u5173\u7f51\u9875\u94fe\u63a5\uff0c\u6743\u91cd\u4e3a {arg1}\u3002\")\n    else:\n        output_messages.append(\"\u7f51\u9875\u4e2d\u4e0d\u5b58\u5728\u56fd\u7f51\u76f8\u5173\u7f51\u9875\u94fe\u63a5\u3002\")\n\n    # \u5904\u7406\u56fd\u7f51\u76f8\u5173\u8bcd\u6c47\u6743\u91cd\n    if 0 < arg2 < 100:\n        output_messages.append(f\"\u7f51\u9875\u4e2d\u5b58\u5728\u56fd\u7f51\u76f8\u5173\u7684\u8bcd\u6c47\uff0c\u6743\u91cd\u4e3a {arg2}\u3002\")\n    elif arg2 >= 100:\n        output_messages.append(f\"\u7f51\u9875\u4e2d\u5b58\u5728\u56fd\u7f51\u76f8\u5173\u7684\u8bcd\u6c47\uff0c\u6743\u91cd\u4e3a 100\u3002\")\n    else:\n        output_messages.append(\"\u7f51\u9875\u4e2d\u4e0d\u5b58\u5728\u56fd\u7f51\u76f8\u5173\u7684\u8bcd\u6c47\u3002\")\n\n    # \u5904\u7406\u56fe\u6807\u6743\u91cd\n    if arg3 > 0:\n        output_messages.append(f\"\u7f51\u9875\u4e2dicon\u4e3a\u56fd\u7f51\u7684\u56fe\u6807\uff0c\u6743\u91cd\u4e3a 100\u3002\")\n    else:\n        output_messages.append(\"\u7f51\u9875\u4e2dicon\u4e0d\u4e3a\u56fd\u7f51\u7684\u56fe\u6807\u3002\")\n\n    # \u5904\u7406\u6807\u9898\u6743\u91cd\n    if 0 < arg4 < 100:\n        output_messages.append(f\"\u7f51\u9875Title\u6709\u56fd\u7f51\u76f8\u5173\u5b57\u6837\uff0c\u6743\u91cd\u4e3a {arg4}\u3002\")\n    elif arg4 >= 100:\n        output_messages.append(f\"\u7f51\u9875Title\u6709\u56fd\u7f51\u76f8\u5173\u5b57\u6837\uff0c\u6743\u91cd\u4e3a 100\u3002\")\n    else:\n        output_messages.append(\"\u7f51\u9875Title\u6ca1\u6709\u56fd\u7f51\u76f8\u5173\u5b57\u6837\u3002\")\n\n    result_str = \"\".join(output_messages)\n\n    return {\n        \"result\": result_str\n    }\n    ", "code_language": "python3", "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "outputs": {"result": {"children": null, "type": "string"}}, "selected": false, "title": "\u6743\u91cd\u6c47\u603b", "type": "code", "variables": [{"value_selector": ["1756371982541", "text"], "variable": "arg1"}, {"value_selector": ["1753526157254", "count"], "variable": "arg2"}, {"value_selector": ["1756371993821", "text"], "variable": "arg3"}, {"value_selector": ["1756372002368", "text"], "varia