\u95ee /favicon.ico \u548c /assets/images/favicon.ico \u8def\u5f84\u3002", "is_team_authorization": true, "output_schema": null, "paramSchemas": [{"name": "url", "label": {"en_US": "url", "zh_Hans": "url", "pt_BR": "url", "ja_JP": "url"}, "placeholder": {"en_US": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "zh_Hans": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "pt_BR": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "ja_JP": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002"}, "scope": null, "auto_generate": null, "template": null, "required": true, "default": null, "min": null, "max": null, "precision": null, "options": [], "type": "string", "human_description": {"en_US": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "zh_Hans": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "pt_BR": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002", "ja_JP": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002"}, "form": "llm", "llm_description": "\u8981\u68c0\u67e5\u7684\u7f51\u7ad9\u7684\u5b8c\u6574 URL (\u4f8b\u5982: https://www.example.com)\u3002"}], "params": {"url": ""}, "selected": false, "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044"}, "position": {"x": 2028, "y": 260}, "targetPosition": "left", "sourcePosition": "right", "zIndex": 1002, "parentId": "1753520887044", "positionAbsolute": {"x": 3559.142857142857, "y": 964.4285714285716}, "width": 244, "height": 54, "selected": false}, {"data": {"code": "import socket\nfrom urllib.parse import urlparse\nimport idna\nimport re\n\ndef is_valid_ipv4(address: str) -> bool:\n    \"\"\"\u68c0\u67e5\u662f\u5426\u4e3a\u5408\u6cd5 IPv4 \u5730\u5740\"\"\"\n    try:\n        socket.inet_pton(socket.AF_INET, address)\n        if address.count(''.'') == 3 and all(0 <= int(part) <= 255 for part in address.split(''.'')):\n            return True\n        return False\n    except (socket.error, ValueError):\n        return False\n\ndef is_valid_ipv6(address: str) -> bool:\n    \"\"\"\u68c0\u67e5\u662f\u5426\u4e3a\u5408\u6cd5 IPv6 \u5730\u5740\"\"\"\n    try:\n        socket.inet_pton(socket.AF_INET6, address)\n        return True\n    except socket.error:\n        return False\n\ndef is_valid_domain_format(hostname: str) -> bool:\n    \"\"\"\u68c0\u67e5\u57df\u540d\u683c\u5f0f\u662f\u5426\u5408\u6cd5\uff08\u5fc5\u987b\u542b\u70b9\u53f7\u6216\u662flocalhost\uff09\"\"\"\n    return ''.'' in hostname or hostname.lower() == \"localhost\"\n\ndef normalize_hostname(hostname: str) -> str:\n    \"\"\"\u5c06\u57df\u540d\u4e2d\u7684\u5404\u79cd\u975e\u6807\u51c6\u70b9\u53f7\u66ff\u6362\u4e3a ASCII \u70b9\u53f7\"\"\"\n    if not hostname:\n        return hostname\n    return (\n        hostname\n        .replace(\"\uff0e\", \".\")  # \u5168\u89d2\u70b9\n        .replace(\"\u3002\", \".\")  # \u4e2d\u6587\u53e5\u53f7\n        .replace(\"\uff61\", \".\")  # \u534a\u89d2\u65e5\u6587\u70b9\n        .strip()\n    )\n\ndef contains_multiple_urls(text: str) -> bool:\n    \"\"\"\u68c0\u6d4b\u6587\u672c\u4e2d\u662f\u5426\u5305\u542b\u591a\u4e2aURL\uff08\u901a\u8fc7http://\u6216https://\u7684\u51fa\u73b0\u6b21\u6570\u5224\u65ad\uff09\"\"\"\n    url_pattern = re.compile(r''https?://'', re.IGNORECASE)\n    matches = url_pattern.findall(text)\n    return len(matches) >= 2\n\ndef main(url_or_ip: str) -> dict:\n    # \u9884\u5904\u7406\n    url_or_ip = url_or_ip.strip()\n\n    # \u68c0\u6d4b\u662f\u5426\u5305\u542b\u591a\u4e2a URL\n    if contains_multiple_urls(url_or_ip):\n        return {\"result\": 3}\n\n    # \u68c0\u6d4b\u662f\u5426\u5305\u542b\u7a7a\u683c\u5206\u9694\u7684\u591a\u4e2a\u8f93\u5165\n    if '' '' in url_or_ip:\n        return {\"result\": 3}\n\n    # \u68c0\u67e5\u662f\u5426\u4e3a\u7eaf IP\n    if is_valid_ipv4(url_or_ip) or is_valid_ipv6(url_or_ip):\n        return {\"result\": 1}\n\n    # \u6dfb\u52a0\u534f\u8bae\u5934\u4ee5\u4fbf\u89e3\u6790\n    url_fixed = url_or_ip\n    if not url_or_ip.startswith((''http://'', ''https://'')):\n        url_fixed = ''http://'' + url_or_ip\n\n    try:\n        parsed = urlparse(url_fixed)\n        hostname = parsed.hostname\n\n        if not hostname:\n            return {\"result\": 3}\n\n        # \u57df\u540d\u7edf\u4e00\u6807\u51c6\u5316\n        hostname = normalize_hostname(hostname)\n\n        # \u68c0\u67e5\u89e3\u6790\u540e\u7684\u4e3b\u673a\u540d\u662f\u5426\u4e3a IP\n        if is_valid_ipv4(hostname) or is_valid_ipv6(hostname):\n            return {\"result\": 2}\n\n        # \u770b\u8d77\u6765\u50cf IPv4 \u4f46\u65e0\u6548\n        if re.match(r\"^\\d+\\.\\d+\\.\\d+\\.\\d+$\", hostname) or (\":\" in hostname and not is_valid_ipv6(hostname)):\n            return {\"result\": 3}\n\n        # \u9a8c\u8bc1\u57df\u540d\u683c\u5f0f\u548c IDNA \u7f16\u7801\n        try:\n            idna.encode(hostname)\n            if is_valid_domain_format(hostname):\n                return {\"result\": 2}\n            else:\n                return {\"result\": 3}\n        except idna.IDNAError:\n            return {\"result\": 3}\n\n    except Exception:\n        return {\"result\": 3}", "code_language": "python3", "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "outputs": {"result": {"children": null, "type": "number"}}, "selected": false, "title": "\u8f93\u5165\u5224\u65ad", "type": "code", "variables": [{"value_selector": ["1753520887044", "item"], "variable": "url_or_ip"}]}, "height": 54, "id": "1754362488071", "parentId": "1753520887044", "position": {"x": 508, "y": 109}, "positionAbsolute": {"x": 2039.1428571428569, "y": 813.4285714285716}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244, "zIndex": 1002}, {"data": {"cases": [{"case_id": "true", "conditions": [{"comparison_operator": "=", "id": "a44d185b-5a91-44d1-9e3f-9ae6d6d2e65e", "value": "1", "varType": "number", "variable_selector": ["1754362488071", "result"]}, {"comparison_operator": "=", "id": "1f4395de-edeb-4d78-940b-10791937b529", "value": "2", "varType": "number", "variable_selector": ["1754362488071", "result"]}], "id": "true", "logical_operator": "or"}], "desc": "", "isInIteration": true, "isInLoop": false, "iteration_id": "1753520887044", "selected": false, "title": "\u6761\u4ef6\u5206\u652f 4", "type": "if-else"}, "height": 152, "id": "1754362569313", "parentId": "1753520887044", "position": {"x": 812, "y": 60}, "positionAbsolute": {"x": 2343.142857142857, "y": 764.4285714285716}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244, "zIndex": 1002}], "edges": [{"data": {"isInIteration": false, "isInLoop": false, "sourceType": "start", "targetType": "if-else"}, "id": "1753517223628-source-1753517292273-target", "selected": false, "source": "1753517223628", "sourceHandle": "source", "target": "1753517292273", "targetHandle": "target", "type": "custom", "zIndex": 0}, {"data": {"isInIteration": false, "isInLoop": false, "sourceType": "if-else", "targetType": "code"}, "id": "1753517292273-true-1753517388554-target", "selected": false, "source": "1753517292273", "sourceHandle": "true", "target": "1753517388554", "targetHandle": "target", "type": "custom", "zIndex": 0}, {"data": {"isInIteration": false, "isInLoop": false, "sourceType": "code", "targetType": "end"}, "id": "1753517388554-source-1753517444182-target", "selected": false, "source": "1753517388554", "sourceHandle": "source", "target": "1753517444182", "targetHandle": "target", "type": "custom", "zIndex": 0}, {"data": {"isInIteration": false