	 ('ef549fe7-7c14-44f4-90eb-2c3cb8a76736'::uuid,'5a1eb0a8-9ccf-4a4a-9101-7d6273ee5bb3'::uuid,'cffd0195-5924-468e-b642-1c3c0d12784a'::uuid,'workflow','draft','{"nodes": [{"data": {"desc": "https://www.baidu.com", "selected": false, "title": "\u5f00\u59cb", "type": "start", "variables": [{"label": "url", "max_length": null, "options": [], "required": true, "type": "text-input", "variable": "url"}]}, "height": 118, "id": "1724639372563", "position": {"x": -526.1942144267209, "y": 253}, "positionAbsolute": {"x": -526.1942144267209, "y": 253}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"code": "import json\nimport re\n\ndef clean_markdown(text: str) -> str:\n    if not text:\n        return \"\"\n    \n    # 1. \u79fb\u9664\u6240\u6709 URL\uff08http, https, javascript\uff09\n    text = re.sub(r''(https?://[^\\s\"\\''\\\\\\]\\)]+|javascript:[^\\s\"\\''\\\\\\]\\)]+)'', '''', text)\n\n    # 2. \u53bb\u6389 Markdown \u4e2d base64 \u56fe\u7247\u8bed\u6cd5 ![alt](data:image/...)\n    text = re.sub(r''!\\[.*?\\]\\(data:image\\/[a-zA-Z]+;base64,[^\\)]*?\\)'', '''', text)\n\n    # 3. \u53bb\u6389 Markdown \u56fe\u7247\u8bed\u6cd5 ![alt](url)\n    text = re.sub(r''!\\[.*?\\]\\(.*?\\)'', '''', text)\n\n    # 4. \u53bb\u6389 Markdown \u94fe\u63a5 [text](url) \u2192 \u53ea\u4fdd\u7559 text\n    text = re.sub(r''\\[([^\\]]+)\\]\\(.*?\\)'', r''\\1'', text)\n\n    # 5. \u79fb\u9664 HTML \u4e2d base64 \u56fe\u7247\u6807\u7b7e\n    text = re.sub(r''<img\\s+[^>]*src=[\"\\'']data:image\\/[a-zA-Z]+;base64,[^\"\\'']*[\"\\''][^>]*>'', '''', text, flags=re.IGNORECASE)\n\n    # 6. \u79fb\u9664 HTML \u6807\u7b7e\n    text = re.sub(r''<[^>]+>'', '''', text)\n\n    # 7. \u6e05\u7406\u591a\u4f59\u7684\u6362\u884c\u548c\u7a7a\u683c\n    text = re.sub(r''\\n+'', ''\\n'', text)  # \u5408\u5e76\u591a\u884c\u6362\u884c\u7b26\n    text = re.sub(r''\\s{2,}'', '' '', text)  # \u5408\u5e76\u591a\u4f59\u7a7a\u683c\n    return text.strip()\n\n\ndef main(body):\n    result = {''success'': ''false''}\n    try:\n        data = json.loads(body)\n        if data.get(\"success\"):\n            result[\"success\"] = \"true\"\n            raw_markdown = data[\"data\"].get(\"markdown\", \"\")\n            result[\"markdown\"] = clean_markdown(raw_markdown)\n\n            metadata = data[\"data\"].get(\"metadata\", {})\n            result[\"title\"] = metadata.get(\"title\", metadata.get(\"ogTitle\", \"\"))\n        return result\n    except json.JSONDecodeError:\n        return result\n    except Exception:\n        return result", "code_language": "python3", "dependencies": [], "desc": "", "outputs": {"markdown": {"children": null, "type": "string"}, "success": {"children": null, "type": "string"}, "title": {"children": null, "type": "string"}}, "selected": false, "title": "\u4ee3\u7801\u6267\u884c", "type": "code", "variables": [{"value_selector": ["1724654533265", "body"], "variable": "body"}]}, "height": 54, "id": "1724653169366", "position": {"x": 1135.6088650109668, "y": 164.51455679574894}, "positionAbsolute": {"x": 1135.6088650109668, "y": 164.51455679574894}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"authorization": {"config": null, "type": "no-auth"}, "body": {"data": [{"type": "text", "value": "{\n    \"url\":\"{{#1724639372563.url#}}\"\n}"}], "type": "raw-text"}, "default_value": [{"key": "body", "type": "string", "value": "\"\""}, {"key": "status_code", "type": "number", "value": 0}, {"key": "headers", "type": "object", "value": "{}"}], "desc": "", "error_strategy": "default-value", "headers": "Content-Type:application/json", "method": "post", "params": "", "retry_config": {"max_retries": 3, "retry_enabled": true, "retry_interval": 100}, "selected": true, "ssl_verify": true, "timeout": {"connect": 30, "max_connect_timeout": 0, "max_read_timeout": 0, "max_write_timeout": 0, "read": 3, "write": 3}, "title": "HTTP \u8bf7\u6c42